(()=>{'use strict';
const D=window.HL,$=s=>document.querySelector(s),end=new Date(D.end),day=86400000;
const state={view:'overview',period:28,supervisor:'all',query:'',callStatus:'all',page:0,sort:'quality',coaching:'all'};
let plans={};try{plans=JSON.parse(localStorage.getItem('homelands-demo-coaching-v1')||'{}');if(!plans||Array.isArray(plans)||typeof plans!=='object')plans={};}catch{}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>Number(n).toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}),pct=(n,d=1)=>n===null?'—':fmt(n,d)+'%',dateLabel=(date,opts={day:'numeric',month:'short'})=>new Intl.DateTimeFormat('en-GB',{...opts,timeZone:'Asia/Colombo'}).format(new Date(date));
const agent=id=>D.agents.find(a=>a.id===id),sup=id=>D.supervisors.find(s=>s.id===id),clamp=n=>Math.min(100,Math.max(0,n));
const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',teams:'M4 21v-7h16v7M12 8v6M5 3h14v5H5zM6 17v4M18 17v4',agents:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',calls:'M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6 19.8 19.8 0 0 1-3-8.7A2 2 0 0 1 4.2 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L8.1 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.6 2z',coaching:'M9 3h6v4H9zM9 5H5v16h14V5h-4M8 12l2 2 5-5M8 18h7',quality:'M12 3l8 4v5c0 5-8 9-8 9s-8-4-8-9V7zM8 12l3 3 5-6',sentiment:'M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0M8 14s1 3 4 3 4-3 4-3M8 9h.01M16 9h.01',arrow:'M5 12h14M13 6l6 6-6 6'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.quality}"/></svg>`;
const selectedAgents=()=>D.agents.filter(a=>state.supervisor==='all'||a.supervisorId===state.supervisor);
function selectCalls(previous=false){const hi=+end-(previous?state.period*day:0),lo=hi-state.period*day;return D.calls.filter(c=>+new Date(c.date)>=lo&&+new Date(c.date)<hi&&(state.supervisor==='all'||c.supervisorId===state.supervisor));}
function metrics(calls){const ready=calls.filter(c=>!c.review),earned=ready.reduce((s,c)=>s+c.earned,0),max=ready.reduce((s,c)=>s+c.max,0);const eligible=calls.reduce((s,c)=>s+c.scores.filter(x=>x.status!=='not_applicable').reduce((t,x)=>t+x.max,0),0);const assessed=calls.reduce((s,c)=>s+c.max,0);const verified=calls.filter(c=>c.greeting!=='unverifiable');return{count:calls.length,ready:ready.length,review:calls.length-ready.length,quality:max?earned/max*100:null,greeting:verified.length?100*verified.filter(c=>c.greeting==='approved').length/verified.length:null,greetingKnown:verified.length,improved:calls.filter(c=>c.finish>c.start).length,stable:calls.filter(c=>c.finish===c.start).length,declined:calls.filter(c=>c.finish<c.start).length,coverage:eligible?assessed/eligible*100:0,minutes:calls.reduce((s,c)=>s+c.duration/60,0),visits:calls.filter(c=>c.outcome==='Site visit agreed').length,followup:calls.filter(c=>c.outcome==='Follow-up agreed').length};}
function agentRows(calls=selectCalls()){return selectedAgents().map(a=>({...a,m:metrics(calls.filter(c=>c.agentId===a.id)),prev:metrics(selectCalls(true).filter(c=>c.agentId===a.id))})).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name):(b.m.quality??-1)-(a.m.quality??-1));}
const change=(a,b)=>a===null||b===null?'<span>Not enough comparison data</span>':`<span class="${a>=b?'trend-up':'trend-down'}">${a>=b?'↗':'↘'} ${fmt(Math.abs(a-b),1)} pp</span> vs previous ${state.period} days`;
const badge=(text,kind='neutral')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const statusBadge=c=>c.review?badge('Needs review','warn'):badge('Evaluated','good');
const qualityBadge=q=>q===null?badge('Needs review','warn'):q>=85?badge('On track','good'):q>=75?badge('Developing','neutral'):badge('Coach next','warn');
function person(a,subtitle=true){return`<div class="person"><span class="avatar">${a.initials}</span><div><button class="name-button" data-action="agent" data-id="${a.id}">${a.name}</button>${subtitle?`<small>${sup(a.supervisorId).team}</small>`:''}</div></div>`;}
function kpi(label,value,foot,type='quality',primary=false){return`<article class="kpi ${primary?'primary':''}"><div class="kpi-top">${label}<span class="metric-icon">${icon(type)}</span></div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></article>`;}
function kpis(){const m=metrics(selectCalls()),p=metrics(selectCalls(true));return`<section class="kpis" aria-label="Performance summary">${kpi('Call quality',pct(m.quality),change(m.quality,p.quality),'quality',true)}${kpi('Calls analysed',fmt(m.count),`${fmt(m.ready)} evaluated · ${fmt(m.review)} need review`,'calls')}${kpi('Approved opening',pct(m.greeting),`${fmt(m.greetingKnown)} verifiable openings`,'quality')}${kpi('Sentiment improved',pct(m.count?100*m.improved/m.count:null),`${fmt(m.improved)} calls ended more positively`,'sentiment')}</section>`;}
function trendChart(calls){const bins=[];const step=state.period/7;for(let i=0;i<7;i++){const lo=+end-(state.period-i*step)*day,hi=lo+step*day;const m=metrics(calls.filter(c=>+new Date(c.date)>=lo&&+new Date(c.date)<hi));bins.push({label:dateLabel(lo),value:m.quality});}const x=i=>48+i*83.5,y=v=>195-(v-40)*2.7;const available=bins.filter(x=>x.value!==null);if(!available.length)return'<div class="empty">No evaluated calls in this period.</div>';const points=bins.filter(b=>b.value!==null).map(b=>[x(bins.indexOf(b)),y(b.value)]);const line=points.map(([a,b],i)=>(i?'L':'M')+a+','+b).join(' ');return`<svg class="chart" viewBox="0 0 600 230" role="img" aria-label="Call quality over the selected period. Target 85 percent. ${bins.map(b=>b.label+': '+pct(b.value)).join('; ')}"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b84458" stop-opacity=".13"/><stop offset="1" stop-color="#b84458" stop-opacity="0"/></linearGradient></defs>${[40,60,80,100].map(v=>`<line class="grid" x1="44" x2="570" y1="${y(v)}" y2="${y(v)}"/><text x="8" y="${y(v)+4}">${v}%</text>`).join('')}<path d="${line} L${points.at(-1)[0]},195 L${points[0][0]},195 Z" fill="url(#fill)"/><line class="target-line" x1="44" x2="570" y1="${y(85)}" y2="${y(85)}"/><path class="data-line" d="${line}"/>${bins.map((b,i)=>`${b.value!==null?`<circle class="data-point" cx="${x(i)}" cy="${y(b.value)}" r="4"><title>${b.label}: ${pct(b.value)}</title></circle>`:''}<text text-anchor="middle" x="${x(i)}" y="220">${b.label}</text>`).join('')}</svg>`;}
function teamComparisons(){const rows=D.supervisors.filter(s=>state.supervisor==='all'||s.id===state.supervisor).map(s=>({...s,m:metrics(selectCalls().filter(c=>c.supervisorId===s.id))})).sort((a,b)=>(b.m.quality??0)-(a.m.quality??0));return rows.map(s=>`<div class="team-row"><div class="team-main"><div class="team-name"><span class="avatar" style="color:${s.color};background:${s.color}12">${s.initials}</span><div><button data-action="team" data-id="${s.id}">${s.team}</button><small>${s.name}</small></div></div><strong class="team-score">${pct(s.m.quality)}</strong></div><div class="track team-track"><i style="width:${s.m.quality||0}%;background:${s.color}"></i></div><div class="team-meta"><span>4 agents · ${fmt(s.m.count)} calls</span><span>${fmt(s.m.review)} to review</span></div></div>`).join('');}
function leaderboard(limit){const rows=agentRows().slice(0,limit||99);return`<div class="table-wrap"><table><thead><tr><th>Agent</th><th><button class="score-order" data-action="sort">Quality ↓</button></th><th>Calls</th><th>Change</th><th>Status</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${person(a)}</td><td class="score">${pct(a.m.quality)}</td><td>${a.m.count}</td><td><span class="mini-trend ${a.m.quality>=a.prev.quality?'trend-up':'trend-down'}">${a.m.quality>=a.prev.quality?'↗':'↘'} ${fmt(Math.abs(a.m.quality-a.prev.quality),1)} pp</span></td><td>${qualityBadge(a.m.quality)}</td></tr>`).join('')}</tbody></table></div>`;}
const advice={greeting:{title:'Make the opening consistent',action:'Practise “ආයුබෝවන්, Home Lands” in the first agent turn. Replay two openings together.'},profiling:{title:'Understand the customer before pitching',action:'Ask about the preferred location, purchase intention and budget. Explore occupation or income only when relevant and without pressure.'},site_visit:{title:'Turn interest into a clear next step',action:'Offer a relevant site visit, then propose a date and time. Respect a decline or a confirmed budget mismatch.'},usps:{title:'Connect a benefit to a customer need',action:'Use an approved project detail and explain why it matters to this customer. Verify the source before making a claim.'},adaptation:{title:'Acknowledge the budget mismatch',action:'Acknowledge the customer’s limit, explore a suitable alternative and agree a realistic next step.'},closure:{title:'Close with a helpful recap',action:'Summarise the agreed information or next step, confirm ownership and end with a warm farewell.'},convincing:{title:'Give precise, verified answers',action:'Check the approved property record, answer the specific question and avoid promises you cannot verify.'},communication:{title:'Listen, clarify, then respond',action:'Let the customer finish. Reflect the requirement back before moving to the next question.'},tone:{title:'Keep the delivery warm',action:'Listen to the recording together and practise a calm, welcoming response.'},location:{title:'Make location details useful',action:'Explain a verified access detail in relation to the customer’s needs.'},language:{title:'Make the explanation easy to follow',action:'Use the customer’s preferred language, explain jargon and check understanding.'}};
function opportunities(){const cs=selectCalls();return selectedAgents().map(a=>{const ac=cs.filter(c=>c.agentId===a.id&&!c.review);const weak=D.criteria.map(cr=>{const eligible=ac.filter(c=>c.scores.find(s=>s.id===cr.id).status==='scored');const missed=eligible.filter(c=>c.scores.find(s=>s.id===cr.id).points<cr.max*2/3);return{...cr,count:missed.length,calls:missed};}).sort((a,b)=>b.count-a.count)[0];return{agent:a,...weak,plan:plans[a.id]||null};}).filter(o=>o.count>0).sort((a,b)=>b.count-a.count);}
function priorities(){return opportunities().slice(0,3).map((o,i)=>`<article class="priority"><span class="priority-num">0${i+1}</span><div><h3>${advice[o.id].title}</h3><p>${o.agent.name} · ${o.count} calls with this opportunity</p><button data-action="plan" data-id="${o.agent.id}">${o.plan?'View coaching plan':'Prepare coaching plan'} →</button></div></article>`).join('')||'<p class="small-note">No coaching opportunities in this view.</p>';}
function sentimentPanel(){const m=metrics(selectCalls()),den=m.count||1;return`<article class="panel"><div class="panel-head"><div><h2>How customers leave the conversation</h2><p class="panel-sub">Change from opening to closing · estimated sentiment</p></div></div><div class="panel-body"><div class="sentiment-bar" role="img" aria-label="${m.improved} improved, ${m.stable} unchanged, ${m.declined} declined"><span style="width:${m.improved/den*100}%"></span><span style="width:${m.stable/den*100}%"></span><span style="width:${m.declined/den*100}%"></span></div><div class="sentiment-stats"><div><strong style="color:var(--teal)">${pct(100*m.improved/den,0)}</strong><small>Improved · ${m.improved}</small></div><div><strong>${pct(100*m.stable/den,0)}</strong><small>Unchanged · ${m.stable}</small></div><div><strong style="color:#b57064">${pct(100*m.declined/den,0)}</strong><small>Declined · ${m.declined}</small></div></div></div><div class="insight-strip">Sentiment is separate from QA and sales outcomes. <strong>It is not a CSAT survey.</strong></div></article>`;}
function outcomesPanel(){const calls=selectCalls(),m=metrics(calls);return`<article class="panel"><div class="panel-head"><div><h2>Conversation outcomes</h2><p class="panel-sub">Agreements mentioned in calls · not confirmed sales</p></div></div><div class="panel-body">${['Site visit agreed','Follow-up agreed','Information only','Budget mismatch'].map((x,i)=>{const n=calls.filter(c=>c.outcome===x).length;return`<div class="outcome-row"><span>${x}</span><div class="track"><i style="background:${['#197c74','#677baa','#a9b6c8','#c7936e'][i]};width:${calls.length?100*n/calls.length:0}%"></i></div><strong>${n}</strong></div>`;}).join('')}<p class="small-note">${fmt(m.minutes)} audio minutes in the selected period</p></div></article>`;}
function overview(){const m=metrics(selectCalls());return`${kpis()}<section class="panels"><article class="panel"><div class="panel-head"><div><h2>Call quality over time</h2><p class="panel-sub">Assessed points across evaluated calls</p></div><div class="legend"><span><i></i> Quality</span><span><i class="target"></i> 85% target</span></div></div><div class="panel-body">${trendChart(selectCalls())}<div class="chart-footer"><span>Demo quality target: 85%</span><span>Evidence coverage <strong>${pct(m.coverage)}</strong></span></div></div></article><article class="panel"><div class="panel-head"><div><h2>Supervisor teams</h2><p class="panel-sub">Compare teams, then explore their agents</p></div><button class="text-button" data-action="navigate" data-id="teams">View all →</button></div><div class="panel-body">${teamComparisons()}</div></article></section><section class="panels"><article class="panel"><div class="panel-head table-head"><div><h2>Agent performance</h2><p class="panel-sub">Top agents by call quality · ${selectedAgents().length} in this view</p></div><button class="text-button" data-action="navigate" data-id="agents">All agents →</button></div>${leaderboard(5)}<div class="table-bottom"><span>Score bands are demo targets, not an official performance rating.</span></div></article><article class="panel"><div class="panel-head"><div><h2>Where coaching can help</h2><p class="panel-sub">Recurring opportunities for supervisors</p></div></div><div class="panel-body">${priorities()}</div></article></section><section class="panels">${sentimentPanel()}${outcomesPanel()}</section>`;}
function teamsView(){return`${kpis()}<div class="team-cards">${D.supervisors.filter(s=>state.supervisor==='all'||s.id===state.supervisor).map(s=>{const m=metrics(selectCalls().filter(c=>c.supervisorId===s.id));return`<article class="panel team-card"><div class="eyebrow">SUPERVISOR TEAM</div><h2>${s.team}</h2><div class="supervisor"><span class="avatar" style="color:${s.color};background:${s.color}15">${s.initials}</span><div>${s.name}<small>4 sales agents</small></div></div><div class="big-score">${pct(m.quality)}</div><span class="small-note">Team quality · weighted by assessed points</span><div class="track" style="margin-top:14px"><i style="width:${m.quality||0}%;background:${s.color}"></i></div><div class="mini-grid"><div><strong>${m.count}</strong><small>Calls</small></div><div><strong>${m.review}</strong><small>To review</small></div><div><strong>${pct(m.greeting,0)}</strong><small>Opening</small></div></div><button class="button secondary" data-action="team" data-id="${s.id}">Explore team ${icon('arrow')}</button></article>`;}).join('')}</div><article class="panel"><div class="panel-head table-head"><div><h2>Every agent, with clear ownership</h2><p class="panel-sub">Click an agent to open their scorecard, calls and coaching plan</p></div></div>${leaderboard()}</article>`;}
function agentsView(){const rows=agentRows().filter(a=>a.name.toLowerCase().includes(state.query.toLowerCase()));return`${kpis()}<article class="panel"><div class="panel-head"><div><h2>Sales agent performance</h2><p class="panel-sub">QA results and customer experience in one view</p></div></div><div class="toolbar"><input class="search" id="search" placeholder="Search agent name…" aria-label="Search agent name" value="${esc(state.query)}"><label>Sort by<select id="agent-sort"><option value="quality" ${state.sort==='quality'?'selected':''}>Quality: highest first</option><option value="name" ${state.sort==='name'?'selected':''}>Agent name</option></select></label><span class="small-note">${rows.length} agents</span></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Supervisor</th><th>Quality</th><th>Calls</th><th>Opening</th><th>Sentiment ↑</th><th>To review</th><th>Status</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${person(a)}</td><td>${sup(a.supervisorId).name}</td><td class="score">${pct(a.m.quality)}</td><td>${a.m.count}</td><td>${pct(a.m.greeting,0)}</td><td>${pct(a.m.count?100*a.m.improved/a.m.count:null,0)}</td><td>${a.m.review}</td><td>${qualityBadge(a.m.quality)}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty"><h3>No matching agents</h3>Try another name or reset the filters.</div>':''}</div><div class="table-bottom"><span>“Sentiment ↑” = share of calls with an improved closing sentiment.</span><span>Quality excludes calls awaiting review.</span></div></article>`;}
function callRows(list){return list.map(c=>`<tr><td><button class="name-button" data-action="call" data-id="${c.id}">${c.id}</button><div class="small-note">${dateLabel(c.date)}</div></td><td>${person(agent(c.agentId),false)}</td><td>${c.project}</td><td>${Math.floor(c.duration/60)}:${String(c.duration%60).padStart(2,'0')}</td><td class="${c.review?'score muted':'score'}">${c.review?'Unscored':pct(c.quality)}</td><td>${badge(c.finish>c.start?'Improved':c.finish<c.start?'Declined':'Unchanged',c.finish>c.start?'good':c.finish<c.start?'bad':'neutral')}</td><td>${c.outcome}</td><td>${statusBadge(c)}</td></tr>`).join('');}
function callsView(){const list=selectCalls().filter(c=>(state.callStatus==='all'||(state.callStatus==='review'?c.review:state.callStatus==='declined'?c.finish<c.start:!c.review))&&[c.id,agent(c.agentId).name,c.project].some(s=>s.toLowerCase().includes(state.query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));const pages=Math.max(1,Math.ceil(list.length/12));state.page=Math.min(state.page,pages-1);return`<div class="page-lead"><p>Open any call for its evidence, sentiment change and score breakdown.</p><span class="demo-pill">Illustrative transcripts · recordings not connected</span></div><article class="panel"><div class="toolbar"><input class="search" id="search" placeholder="Search call, agent or project…" aria-label="Search calls" value="${esc(state.query)}"><label>Show<select id="call-status"><option value="all">All calls</option><option value="evaluated" ${state.callStatus==='evaluated'?'selected':''}>Evaluated</option><option value="review" ${state.callStatus==='review'?'selected':''}>Needs review</option><option value="declined" ${state.callStatus==='declined'?'selected':''}>Sentiment declined</option></select></label><span class="small-note">${fmt(list.length)} calls</span></div><div class="table-wrap"><table><thead><tr><th>Call / date</th><th>Agent</th><th>Project (demo)</th><th>Length</th><th>Quality</th><th>Sentiment</th><th>Outcome</th><th>Evaluation</th></tr></thead><tbody>${callRows(list.slice(state.page*12,(state.page+1)*12))}</tbody></table>${!list.length?'<div class="empty"><h3>No calls match this view</h3>Try another search or reset the filters.</div>':''}</div><div class="table-bottom"><span>${list.length?state.page*12+1:0}–${Math.min((state.page+1)*12,list.length)} of ${fmt(list.length)}</span><div class="pagination"><button data-action="page" data-id="prev" ${state.page===0?'disabled':''}>← Previous</button><span>${state.page+1} / ${pages}</span><button data-action="page" data-id="next" ${state.page>=pages-1?'disabled':''}>Next →</button></div></div></article>`;}
function coachingView(){const ops=opportunities().filter(o=>state.coaching==='all'||(state.coaching==='open'?!o.plan||o.plan.status!=='completed':o.plan?.status==='completed'));return`<div class="notice info">Coaching actions are saved only in this browser for the demo. Nothing is sent to agents or supervisors.</div><div class="page-lead"><p>One priority per agent, based on recurring gaps in evaluated calls.</p><div class="coaching-tabs" aria-label="Coaching status filter">${[['all','All priorities'],['open','Open'],['completed','Completed']].map(([id,n])=>`<button data-action="coaching-filter" data-id="${id}" class="${state.coaching===id?'active':''}" aria-pressed="${state.coaching===id}">${n}</button>`).join('')}</div></div><section class="coaching-grid">${ops.map(o=>`<article class="panel coaching-card"><div class="coaching-meta">${badge(o.plan?.status==='completed'?'Completed':o.plan?'Planned':'Suggested',o.plan?.status==='completed'?'good':o.plan?'neutral':'warn')}<span>${o.count} relevant calls</span></div><h3>${advice[o.id].title}</h3><p>${advice[o.id].action}</p>${person(o.agent)}<p>Supervisor: <strong>${sup(o.agent.supervisorId).name}</strong>${o.plan?.date?`<br>Review date: ${dateLabel(o.plan.date+'T12:00:00Z')}`:''}</p><button class="button secondary" data-action="plan" data-id="${o.agent.id}">${o.plan?'Review plan':'Prepare plan'} →</button></article>`).join('')||'<div class="panel empty"><h3>No priorities in this view</h3>Completed plans appear here after a supervisor marks them complete.</div>'}</section>`;}
const viewMeta={overview:['Every conversation counts.','A clear view of your sales teams. A better next conversation.','Overview'],teams:['Strong teams start with visibility.','Compare supervisor teams and find where support makes a difference.','Supervisor teams'],agents:['The people behind the performance.','Recognise strong conversations. Give every agent a clear path to improve.','Sales agents'],calls:['From a score to the conversation.','Explore call quality, evidence and how the customer felt by the end.','Call explorer'],coaching:['Turn insight into better conversations.','Focused coaching, owned by each agent’s supervisor.','Coaching']};
function render(keepFocus=false){const active=keepFocus?document.activeElement:null,pos=active?.selectionStart;const meta=viewMeta[state.view];$('#navigation').innerHTML=Object.entries(viewMeta).map(([id,v])=>`<a class="nav-link ${id===state.view?'active':''}" href="#${id}" ${id===state.view?'aria-current="page"':''}>${icon(id)}${v[2]}${id==='agents'?'<span class="nav-count">12</span>':''}</a>`).join('');$('#page-title').textContent=meta[0];$('#page-subtitle').textContent=meta[1];$('#breadcrumb').textContent=meta[2];$('#period').value=state.period;$('#supervisor').value=state.supervisor;$('#period-range').textContent=`${dateLabel(+end-state.period*day)} – ${dateLabel(+end-day)}`;$('#content').innerHTML=({overview,teams:teamsView,agents:agentsView,calls:callsView,coaching:coachingView})[state.view]();if(active?.id==='search'&&$('#search')){$('#search').focus();$('#search').setSelectionRange(pos,pos);}}
function navigate(view){if(!viewMeta[view])return;state.view=view;state.query='';state.page=0;state.callStatus='all';if(location.hash!=='#'+view)history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'smooth'});}
function showDialog(html){const d=$('#detail');$('#detail-content').innerHTML=html;if(!d.open)d.showModal();d.scrollTop=0;}
function detailHeader(label,title,sub){return`<div class="detail-head"><div><div class="eyebrow">${label}</div><h2>${esc(title)}</h2><p>${sub}</p></div><button class="close" data-action="close" aria-label="Close details">×</button></div>`;}
function scorecard(calls){return`<div class="table-wrap"><table class="scorecard"><thead><tr><th>Homelands criterion</th><th>Assessed points</th><th>Attainment</th></tr></thead><tbody>${D.criteria.map(cr=>{const scores=calls.flatMap(c=>c.scores).filter(x=>x.id===cr.id&&x.status==='scored');const max=scores.reduce((s,x)=>s+x.max,0),n=scores.reduce((s,x)=>s+x.points,0);return`<tr><td>${cr.name}</td><td class="earned">${n} / ${max}</td><td><div class="track"><i style="width:${max?100*n/max:0}%;background:${max&&n/max>=.85?'var(--teal)':'#a97172'}"></i></div><small>${max?pct(100*n/max):'Not enough evidence'}</small></td></tr>`;}).join('')}</tbody></table></div>`;}
function openAgent(id){const a=agent(id);if(!a)return;const calls=selectCalls().filter(c=>c.agentId===id),ready=calls.filter(c=>!c.review),m=metrics(calls);showDialog(`${detailHeader('AGENT PERFORMANCE',a.name,`${sup(a.supervisorId).team} · Supervisor: ${sup(a.supervisorId).name} · Last ${state.period} days`)}<div class="detail-body"><div class="kpis">${kpi('Call quality',pct(m.quality),`${m.ready} evaluated calls`,'quality',true)}${kpi('Approved opening',pct(m.greeting),`${m.greetingKnown} verifiable openings`)}${kpi('Awaiting review',m.review,`Evidence coverage ${pct(m.coverage)}`)}</div><div class="panels"><article class="panel"><div class="panel-head table-head"><h2>Quality scorecard</h2></div>${scorecard(ready)}</article><div><article class="panel panel-gap"><div class="panel-body"><h3>Customer sentiment</h3><div class="mini-grid"><div><strong>${m.improved}</strong><small>Improved</small></div><div><strong>${m.stable}</strong><small>Unchanged</small></div><div><strong>${m.declined}</strong><small>Declined</small></div></div><p class="small-note">Estimated change, not measured customer satisfaction.</p></div></article><article class="panel"><div class="panel-body"><h3>Next coaching conversation</h3><p class="small-note">${esc(advice[opportunities().find(o=>o.agent.id===id)?.id||'adaptation'].action)}</p><button class="button full" data-action="plan" data-id="${a.id}">Open coaching plan</button></div></article></div></div><article class="panel"><div class="panel-head table-head"><h2>Recent calls</h2></div><div class="table-wrap"><table><thead><tr><th>Call</th><th>Date</th><th>Quality</th><th>Outcome</th><th>Status</th></tr></thead><tbody>${calls.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(c=>`<tr><td><button class="name-button" data-action="call" data-id="${c.id}">${c.id}</button></td><td>${dateLabel(c.date)}</td><td>${pct(c.quality)}</td><td>${c.outcome}</td><td>${statusBadge(c)}</td></tr>`).join('')}</tbody></table></div></article><p class="footer-note">Scored criteria only; N/A is excluded and missing evidence is never treated as zero. Pending calls are excluded from this agent’s overall QA.</p></div>`);}
const sentimentName=n=>['Concerned','Neutral','Positive'][n+1];
function openCall(id){const c=D.calls.find(c=>c.id===id);if(!c)return;const a=agent(c.agentId),dur=Math.floor(c.duration/60)+':'+String(c.duration%60).padStart(2,'0');const greetingText=c.greeting==='approved'?'ආයුබෝවන්, Home Lands. ඔබට කොහොමද උදව් කරන්න පුළුවන්?':c.greeting==='delayed'?'Hello. ඔබට කොහොමද උදව් කරන්න පුළුවන්?':c.greeting==='partial'?'Hello, Home Lands.':'[opening unclear]';const greetingReason=({approved:'Approved greeting and company name in the first agent turn.',delayed:'Greeting and company name appear later in the conversation.',partial:'Company name is present; the approved Sinhala greeting is missing.',unverifiable:'Opening is unclear. No greeting score is assigned.'})[c.greeting];const transcript=[['00:00','Agent',greetingText],['00:05','Customer','මම බලන්නේ two bedroom ගෙයක්. Budget එක ගැනත් දැනගන්න ඕනේ.'],['00:12','Agent',c.greeting==='delayed'?'ආයුබෝවන්, Home Lands. මැඩම් බලන්නේ කොහේ location එකක්ද?':'මැඩම් බලන්නේ කොහේ location එකක්ද?'],['00:20','Customer','කොළඹට යන්න පහසු තැනක්. දුවගේ job එක නිසා බලන්නේ.'],['00:29','Agent',c.outcome==='Budget mismatch'?'මේ project එකේ ගණන් ඔබේ budget එකට වඩා වැඩියි.':'ඔබේ අවශ්‍යතාවයට ගැළපෙන විකල්ප ගැන බලමු.']];transcript.push([`${Math.floor((c.duration-20)/60)}:${String((c.duration-20)%60).padStart(2,'0')}`,'Agent',c.outcome==='Site visit agreed'?'Saturday උදේ 10ට site visit එකක් කරමුද?':c.outcome==='Follow-up agreed'?'හෙට මම ඔබට නැවත call කරන්නම්.':c.outcome==='Budget mismatch'?'මේ වෙලාවේ ගැළපෙන විකල්පයක් නැහැ. ඔබේ budget එක සටහන් කරගන්නම්.':'මේ විස්තර ඔබට ප්‍රයෝජනවත් වෙයි කියලා හිතනවා.']);transcript.push([`${Math.floor((c.duration-9)/60)}:${String((c.duration-9)%60).padStart(2,'0')}`,'Customer',c.outcome==='Site visit agreed'?'හරි, Saturday 10ට එන්නම්.':c.outcome==='Follow-up agreed'?'හරි, හෙට call කරන්න.':'හරි. ස්තුතියි.']);transcript.push([dur,'Agent','Thank you. සුබ දවසක්.']);showDialog(`${detailHeader('CALL EVIDENCE',c.id,`${a.name} · ${dateLabel(c.date,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · ${c.language}`)}<div class="detail-body"><div class="notice">Fictional demo call. The transcript below is an illustrative extract. No original recording is attached; timestamps and model findings are simulated.</div>${c.review?'<div class="notice info"><strong>Human review required.</strong> Audio or source evidence is incomplete. This call is excluded from the agent’s overall QA until reviewed.</div>':''}<div class="call-numbers"><div><strong>${pct(c.quality)}</strong><small>Overall QA ${c.review?'pending':'score'}</small></div><div><strong>${dur}</strong><small>Recording length</small></div><div><strong>${c.earned} / ${c.max}</strong><small>Available assessed points</small></div></div><article class="panel panel-gap"><div class="panel-body"><h3>Opening greeting</h3>${badge(c.greeting, c.greeting==='approved'?'good':c.greeting==='unverifiable'?'warn':'neutral')}<p class="small-note">${greetingReason}</p></div></article><article class="panel panel-gap"><div class="panel-head"><div><h2>Recording & outcome</h2><p class="panel-sub">${c.project} · fictional project</p></div>${badge(c.outcome)}</div><div class="panel-body"><p class="small-note">Audio playback becomes available when the real recording is connected.</p><h3>Illustrative transcript</h3>${transcript.map(t=>`<div class="transcript-turn"><time>${t[0]}</time><div><strong>${t[1]}</strong><p lang="si">${t[2]}</p></div></div>`).join('')}</div></article><div class="panels"><article class="panel"><div class="panel-body"><h3>Customer sentiment change</h3><div class="sentiment-flow"><strong><small>Opening</small>${sentimentName(c.start)}</strong><span>→</span><strong><small>Closing</small>${sentimentName(c.finish)}</strong></div>${badge(c.finish>c.start?'Improved':c.finish<c.start?'Declined':'Unchanged',c.finish>c.start?'good':c.finish<c.start?'bad':'neutral')}<p class="small-note">Simulated whole-call assessment. The short extract above does not establish this sentiment; real evaluations require evidence from the recording.</p></div></article><article class="panel"><div class="panel-body"><h3>Coaching observation</h3><p style="font-size:14px">Explore what the daughter’s commute requires and acknowledge the customer’s budget before suggesting a next step.</p><p class="small-note">Illustrative coaching example. Supervisor: ${sup(a.supervisorId).name}</p><button class="button secondary" data-action="plan" data-id="${a.id}">Open agent coaching</button></div></article></div><article class="panel"><div class="panel-head table-head"><h2>Call scorecard · maximum 38 points</h2></div><div class="table-wrap"><table class="scorecard"><thead><tr><th>Criterion</th><th>Points</th><th>Evidence status</th></tr></thead><tbody>${c.scores.map(s=>`<tr><td>${D.criteria.find(cr=>cr.id===s.id).name}</td><td>${s.points===null?'—':s.points} / ${s.max}</td><td>${badge(s.status==='scored'?'Assessed':s.status==='not_applicable'?'N/A: budget mismatch':'Insufficient evidence',s.status==='scored'?'neutral':'warn')}</td></tr>`).join('')}</tbody></table></div></article></div>`);}
function openPlan(id){const a=agent(id),o=opportunities().find(o=>o.agent.id===id);if(!a)return;const saved=plans[id],tip=advice[o?.id||'adaptation'];showDialog(`${detailHeader('SUPERVISOR COACHING',a.name,`Owned by ${sup(a.supervisorId).name} · ${sup(a.supervisorId).team}`)}<div class="detail-body"><div class="notice info">Demo only: saved on this device. No message or task is sent to anyone.</div><h3>${tip.title}</h3><p class="small-note">${o?`${o.count} evaluated calls show this recurring opportunity in the selected period.`:'Review the agent’s recent conversations before agreeing on a goal.'}</p><div class="coaching-tip">${tip.action}</div>${o?`<p class="small-note">Example calls: ${o.calls.slice(0,3).map(c=>`<button class="text-button" data-action="call" data-id="${c.id}">${c.id}</button>`).join(' · ')}</p>`:''}<form class="plan-form" id="plan-form" data-agent="${id}"><label for="plan-goal">Coaching goal</label><textarea id="plan-goal" name="goal" required maxlength="1000">${esc(saved?.goal||tip.action)}</textarea><label for="plan-date">Review date</label><input id="plan-date" name="date" type="date" value="${esc(saved?.date||'2026-09-19')}" required><div class="plan-actions">${saved?`<button type="button" class="button secondary" data-action="complete-plan" data-id="${id}">${saved.status==='completed'?'Reopen plan':'Mark completed'}</button>`:'<span></span>'}<button type="submit" class="button">Save demo plan</button></div></form></div>`);}
function openMethod(){showDialog(`${detailHeader('ABOUT THIS DEMO','Know what the numbers mean.','Fictional records · 12 sales agents · 3 supervisor teams')}<div class="detail-body"><ol class="method-list"><li><strong>Source of the scorecard.</strong> The 11 criterion names and 38-point maximum follow the supplied Homelands QA document. Partial-credit rules, the 85% target and performance bands are demo assumptions.</li><li><strong>Quality.</strong> Total earned points ÷ total assessed maximum across fully evaluated calls. Pending-review calls are excluded entirely from aggregate QA. Team scores are weighted by assessed points, not an average of agent percentages.</li><li><strong>Missing evidence is not a zero.</strong> N/A criteria are excluded. Evidence coverage is assessed maximum ÷ eligible maximum across all selected calls. Unknown greetings are excluded from the opening rate and shown in the call evidence.</li><li><strong>Approved opening.</strong> “ආයුබෝවන්, Home Lands” in the first agent turn. A delayed or partial opening is shown separately. These demo calls use Sinhala openings; real language-specific policies must be confirmed.</li><li><strong>Sentiment.</strong> Estimated closing sentiment compared with opening sentiment, using an ordinal scale. This is separate from QA and does not represent CSAT or a sale.</li><li><strong>Comparison.</strong> Each period is compared with the immediately preceding equal-length period. “pp” means percentage points. Demo dates are fixed to 12 September 2026.</li><li><strong>Ownership.</strong> Every agent belongs to one supervisor team. This is a leadership presentation view, not authenticated role-based access.</li><li><strong>Demo boundaries.</strong> All names, calls, outcomes, transcript extracts and findings are invented. No AI calls are made. Coaching edits stay in this browser. Production n8n/GCP data, real audio and authentication are not connected.</li></ol><button class="button secondary" data-action="close">Back to dashboard</button></div>`);}
function exportSummary(){const rows=[['HOMELANDS FICTIONAL DEMO - NOT ACTUAL AGENT PERFORMANCE'],['Period',`${dateLabel(+end-state.period*day)} - ${dateLabel(+end-day)}`],['Supervisor scope',state.supervisor==='all'?'All supervisors':sup(state.supervisor).name],[],['Agent','Supervisor','Team','Calls analysed','Calls evaluated','Needs review','Quality % (evaluated only)','Approved opening %','Sentiment improved %','Evidence coverage %','Coaching status'],...agentRows().map(a=>[a.name,sup(a.supervisorId).name,sup(a.supervisorId).team,a.m.count,a.m.ready,a.m.review,a.m.quality===null?'':a.m.quality.toFixed(2),a.m.greeting?.toFixed(2)||'',a.m.count?(100*a.m.improved/a.m.count).toFixed(2):'',a.m.coverage.toFixed(2),plans[a.id]?.status||'not planned'])];const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Homelands-DEMO-agent-summary.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo summary exported for the current filters.');}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('toast-show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-show'),3500);}
function savePlans(){try{localStorage.setItem('homelands-demo-coaching-v1',JSON.stringify(plans));return true;}catch{toast('Browser storage is unavailable. This plan will last only for this session.');return false;}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const id=a.dataset.id;switch(a.dataset.action){case'navigate':navigate(id);break;case'agent':openAgent(id);break;case'call':openCall(id);break;case'plan':openPlan(id);break;case'team':state.supervisor=id;navigate('agents');break;case'close':$('#detail').close();break;case'method':openMethod();break;case'export':exportSummary();break;case'sort':state.sort='quality';render();break;case'page':state.page+=id==='next'?1:-1;render();break;case'coaching-filter':state.coaching=id;render();break;case'complete-plan':if(plans[id]){plans[id].status=plans[id].status==='completed'?'planned':'completed';const stored=savePlans();render();openPlan(id);if(stored)toast(plans[id].status==='completed'?'Demo coaching plan marked completed.':'Demo coaching plan reopened.');}break;}});
document.addEventListener('change',e=>{if(e.target.id==='period'){state.period=Number(e.target.value);state.page=0;render();}if(e.target.id==='supervisor'){state.supervisor=e.target.value;state.page=0;render();}if(e.target.id==='call-status'){state.callStatus=e.target.value;state.page=0;render();}if(e.target.id==='agent-sort'){state.sort=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;state.page=0;render(true);}});
$('#reset').addEventListener('click',()=>{Object.assign(state,{period:28,supervisor:'all',query:'',callStatus:'all',page:0,sort:'quality',coaching:'all'});render();});
document.addEventListener('submit',e=>{if(e.target.id!=='plan-form')return;e.preventDefault();const id=e.target.dataset.agent;const goal=$('#plan-goal').value.trim();if(!goal){$('#plan-goal').setCustomValidity('Enter a coaching goal.');$('#plan-goal').reportValidity();$('#plan-goal').setCustomValidity('');return;}plans[id]={goal,date:$('#plan-date').value,status:plans[id]?.status||'planned'};const stored=savePlans();$('#detail').close();render();if(stored)toast('Coaching plan saved in this browser.');});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#supervisor').insertAdjacentHTML('beforeend',D.supervisors.map(s=>`<option value="${s.id}">${s.name}</option>`).join(''));
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
state.view=viewMeta[location.hash.slice(1)]?location.hash.slice(1):'overview';render();
// Expose the same visible filter journey to browsers implementing WebMCP.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_dashboard_view',title:'Set Homelands dashboard view',description:'Navigate and filter the fictional Homelands leadership demo. Changes only the visible dashboard, not call data.',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(viewMeta)},period:{type:'integer',enum:[7,14,28]},supervisor_id:{type:'string',enum:['all',...D.supervisors.map(s=>s.id)]}},required:['view','period','supervisor_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!viewMeta[input.view]||![7,14,28].includes(input.period)||!['all',...D.supervisors.map(s=>s.id)].includes(input.supervisor_id))throw new Error('Invalid dashboard filters.');state.period=input.period;state.supervisor=input.supervisor_id;navigate(input.view);return{view:state.view,period:state.period,supervisor:state.supervisor,calls:metrics(selectCalls()).count,demo:true};}})).catch(()=>{});}catch{}}
})();
